do $outer$ declare def text;begin select pg_get_functiondef('public.v2_stripe_allocate(uuid,bigint,text,text)'::regprocedure) into def;def=replace(def,'partner_id uuid;v_allocation jsonb;','partner_id uuid;recovery_recipient uuid;v_allocation jsonb;');def=replace(def,'apgi=floor((available-recovery)',E'if recovery>0 then\n recovery_recipient=nullif(s->>''recoveryRecipientId'','''')::uuid;\n if recovery_recipient is null or not exists(select 1 from public.organisations where id=recovery_recipient and is_active) then raise exception ''The approved development funder requires an identified receiving company'';end if;\n end if;\n apgi=floor((available-recovery)');def=replace(def,'where id=owner and slug=''apgi''','where id=recovery_recipient and slug=''apgi''');def=replace(def,'values(o.id,owner,recovery)','values(o.id,recovery_recipient,recovery)');execute def;end $outer$; create function public.v2_payment_setup_notice() returns trigger language plpgsql security invoker set search_path='' as $$ declare principal record;actor uuid;destination text;begin if tg_op='UPDATE' and (new.country,new.state) is not distinct from(old.country,old.state) then return new;end if;if tg_table_name='v2_stripe_personal_accounts' then actor=new.user_id;destination='/payments/reports?scope=all&table=profiles';else actor=new.owner_id;destination='/payments/reports?scope=all&table=routes';end if;for principal in select user_id from public.platform_principals where user_id is not null and user_id is distinct from actor loop perform public.v2_notice(principal.user_id,'payment-route:'||actor||':'||tg_table_name||':'||new.country||':'||new.state,'A payment recipient updated their receiving-account status: '||replace(new.state,'_',' '),destination,'read',actor);end loop;return new;end $$;create trigger personal_payment_setup_notice after insert or update on public.v2_stripe_personal_accounts for each row execute function public.v2_payment_setup_notice();create trigger company_payment_setup_notice after insert or update on public.v2_stripe_partner_accounts for each row execute function public.v2_payment_setup_notice();revoke all on function public.v2_payment_setup_notice() from public,anon,authenticated;grant execute on function public.v2_payment_setup_notice() to service_role;

